import{_ as o,a0 as p,w as i,s as d,ao as a,I as r,x as e,a1 as u,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"每日Ubuntu小技巧——添加用户到已存在的組 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——添加用户到已存在的組 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——添加用户到已存在的組 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——添加用户到已存在的組 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Adding Users To Existing Groups","title":"每日Ubuntu小技巧——添加用户到已存在的組","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Adding Users To Existing Groups.md","filePath":"[post].md"}'),l={name:"201310/Daily Ubuntu Tips – Adding Users To Existing Groups.md"};function g(b,t,T,m,x,U){const n=p("Link");return i(),d("div",null,[t[11]||(t[11]=a(`<h1 id="每日ubuntu小技巧——添加用户到已存在的組" tabindex="-1">每日Ubuntu小技巧——添加用户到已存在的組 <a class="header-anchor" href="#每日ubuntu小技巧——添加用户到已存在的組" aria-label="Permalink to “每日Ubuntu小技巧——添加用户到已存在的組”">​</a></h1><p>對於剛開始使用Ubuntu的用户和新手來説，尤其是從Ubuntu中不在包含舊式的用户和組的管理工具後，管理用户和組變的富有挑戰性。在先前Ubuntu的版本下，用户可以通過Gnome系統工具下的用户管理工具輕鬆的管理用户和組。</p><p>現在，在Ubuntu上沒有了這個工具，現在唯一的工具也僅僅允許你創建、管理和刪除用户，所以如果你需要在Ubuntu中從組裏面添加或刪除用户，那麼你將需要用到命令列終端或控制台。</p><p>舉個例子，如果你想要讓某些用户訪問文件或提升他們的訪問權限，最好方式就是改變組的權限。你可以創建一個組，接着給這個組正確的權限，在添加用户到組時，用户可以獲得與組相同的權限。</p><p>因為當前Ubuntu不能用工具輕易的管理組權限，這個簡潔的教程，將告訴你如何用命令列完成以上操作，這僅僅是一行代碼，一旦你理解了，這並不難。</p><p>開始吧，按<strong>Ctrl-Alt-T</strong>打開終端。</p><p>查看Ubuntu上所有的組，鍵入命令<code>groupmod</code>並（<strong>連按三次tab鍵</strong>）</p><pre><code>groupmod &lt;連按三次tab鍵&gt;
</code></pre><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/groupsubuntuadduser.png" alt=""></p><p>這會列出現在你係統上的所有用户組，現在添加用户到已存在的組吧，運行下列命令：</p><pre><code>sudo adduser 用户名 組名
</code></pre><p>例如，如果你想添加Richard到sudo組，運行下列命令：</p><pre><code>sudo adduser richard sudo
</code></pre><p>好了，去驗證用户的相關組，運行下列命令：</p><pre><code>id richard
</code></pre><p>試試吧!</p><hr>`,17)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),u(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-users-existing-groups/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-adding-users-existing-groups/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=e("本文由 ",-1)),u(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原創翻譯，",-1)),u(n,{href:"http://linux.cn/"},{default:s(()=>[...t[3]||(t[3]=[e("Linux中國",-1)])]),_:1}),t[6]||(t[6]=e(" 榮譽推出",-1))]),r("p",null,[t[9]||(t[9]=e("譯者：",-1)),u(n,{href:"https://github.com/Luoxcat"},{default:s(()=>[...t[7]||(t[7]=[e("Luoxcat",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),u(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})])])}const w=o(l,[["render",g]]);export{_ as __pageData,w as default};
